      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": null,
      "reason": "This is a diagnostic accuracy review, not a review of complex interventions, so a logic model for intervention components is not applicable."
    }
  ],
  "confidence": 95
